package com.elabrador.mobilenavigation;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

/** Oracle generated by running the upstream Python octree2localprmap_height_ego body. */
public class SourceCostReferenceTest {
    private static String text(DataInputStream input) throws IOException {
        int size=input.readInt();assertTrue(size>=0 && size<=4096);
        byte[] bytes=new byte[size];input.readFully(bytes);
        return new String(bytes,StandardCharsets.UTF_8);
    }

    @Test public void sourcePythonAndAndroidCostProjectionAgreeAcrossClassesColumnsAndPoses() throws Exception {
        InputStream resource=getClass().getResourceAsStream("/source-cost-reference.bin");
        assertNotNull("Run tools/generate_source_cost_reference.py to create the source oracle",resource);
        try(DataInputStream input=new DataInputStream(new BufferedInputStream(resource))) {
            assertEquals(0x53434631,input.readInt());
            String commit=text(input),sourceHash=text(input),configHash=text(input);
            assertEquals("c758acdca0e9d05bb6f52337daefdce9b2b9983e",commit);
            assertEquals(64,sourceHash.length());assertEquals(64,configHash.length());
            int labels=input.readInt();assertEquals(66,labels);
            Map<Integer,Float> config=new HashMap<>();
            for(int i=0;i<labels;i++)config.put(input.readInt(),input.readFloat());
            int cases=input.readInt();assertTrue("Need randomized and targeted source cases",cases>=90);
            int roundedCosts=0,roundedHeights=0;
            for(int c=0;c<cases;c++) {
                String name=text(input);
                float x=input.readFloat(),y=input.readFloat(),z=input.readFloat(),yaw=input.readFloat();
                int leaves=input.readInt();float[] records=new float[leaves*8];
                for(int i=0;i<records.length;i++)records[i]=input.readFloat();
                byte[] expectedCost=new byte[6400],expectedHeight=new byte[6400];
                input.readFully(expectedCost);input.readFully(expectedHeight);
                MapTransform.Grid actual=MapTransform.octree2localprmapSource(records,x,y,z,yaw,config);
                assertEquals(name+" cost shape",6400,actual.cost.length);
                assertEquals(name+" height shape",6400,actual.height.length);
                int expectedKnown=0;
                for(int i=0;i<6400;i++) {
                    int cost=expectedCost[i];
                    if(cost>=0)expectedKnown++;
                    String where=name+" row="+(i/80)+" col="+(i%80);
                    if(cost<0)assertEquals(where+" unknown must stay unknown",-1,actual.cost[i]);
                    else {
                        assertTrue(where+" expected="+cost+" actual="+actual.cost[i],
                                actual.cost[i]>=0 && Math.abs(cost-actual.cost[i])<=1);
                        if(cost!=actual.cost[i])roundedCosts++;
                    }
                    assertTrue(where+" height expected="+expectedHeight[i]+" actual="+actual.height[i],
                            Math.abs((int)expectedHeight[i]-(int)actual.height[i])<=1);
                    if(expectedHeight[i]!=actual.height[i])roundedHeights++;
                }
                assertEquals(name+" observed cells",expectedKnown,actual.known);
            }
            assertEquals("No trailing fixture data",-1,input.read());
            System.out.println("SOURCE_COST_REFERENCE commit="+commit+" cases="+cases+
                    " compared_cells="+(cases*6400)+" config_labels="+labels+
                    " float_cost_rounding_differences="+roundedCosts+
                    " float_height_rounding_differences="+roundedHeights);
        }
    }
}
